  <head>
    <style>
      body {
        background-color: #1a1a1a;
        color: #ffffff;
        font-family: Arial, sans-serif;
        margin: 0;
        padding: 20px;
      }

      .task-id-bar {
        background-color: #2d2d2d;
        padding: 10px 15px;
        border-radius: 5px;
        margin-bottom: 15px;
        border: 1px solid #3d3d3d;
      }
    </style>
  </head>
  <body>
    <div class="task-id-bar" id="data-TaskID" style="display:none;">
      当前任务编号：<span id="task-id-value"></span>
    </div>
  </body>
  <script>
    // 解析世界书条目内容为JSON格式
    function parseEntryContent(content) {
      const lines = content.split('\n');
      const result = {};

      lines.forEach(line => {
        // 移除可能的任务ID前缀
        const cleanLine = line.replace(/^MCC-EA-\d+\./, '').trim();
        if (!cleanLine) return;

        // 处理不同的分隔符（= 或 ：）
        const separator = cleanLine.includes('=') ? '=' : '：';
        const [key, value] = cleanLine.split(separator);

        if (key && value) {
          // 清理键值对
          const cleanKey = key.trim();
          const cleanValue = value.trim();

          // 存储到结果对象
          result[cleanKey] = cleanValue;
        }
      });

      return result;
    }

    // 将JSON数据转换回世界书条目格式
    function convertToEntryFormat(data, taskId) {
      // 检查数据中是否已经包含任务ID
      const hasTaskId = Object.keys(data).some(key => key.startsWith(taskId));

      return Object.entries(data)
        .map(([key, value]) => {
          // 如果键已经包含任务ID，直接使用
          if (key.startsWith(taskId)) {
            return `${key}：${value}`;
          }
          // 否则添加任务ID前缀
          return `${taskId}.${key}：${value}`;
        })
        .join('\n');
    }

    const chat_message = getChatMessages(getCurrentMessageId())[0];
    const message = chat_message.message.split('</thinking>').pop() || chat_message.message;

    // 匹配 <TaskID>任务编号</TaskID>
    const taskIdMatch = message.match(/<TaskID>(.*?)<\/TaskID>/s);
    if (taskIdMatch && taskIdMatch[1]) {
      const taskId = taskIdMatch[1].trim();
      document.getElementById('data-TaskID').style.display = 'block';
      document.getElementById('task-id-value').textContent = taskId;

      // 获取世界书和条目 以taskId为条目标题
      (async () => {
        try {
          const lorebooks = getCharLorebooks({ type: "primary" });
          console.log('获取到的世界书:', lorebooks.primary);

          const entries = await getLorebookEntries(lorebooks.primary);
          console.log('所有条目:', entries);
          //过滤所有含有MCC的世界书条目 并关他们
          const filteredEntriesForClose = entries.filter(entry => entry.comment.includes("MCC"));

          // 关闭所有包含MCC的条目
          if (filteredEntriesForClose.length > 0) {
            const closeEntries = filteredEntriesForClose.map(entry => ({
              uid: entry.uid,
          enabled:true   ,type: "selective",disable:false
            }));

            await setLorebookEntries(lorebooks.primary, closeEntries);
            console.log('已关闭MCC相关条目:', closeEntries);
          }

          const filteredEntries = entries.filter(entry => entry.comment.includes(taskId));
          console.log('过滤后的条目:', filteredEntries);

          if (filteredEntries.length > 0) {
            // 如果条目存在，则更新条目
            const entry = filteredEntries[0];
            // 解析现有条目内容为JSON
            const existingData = parseEntryContent(entry.content);
            console.log('现有条目数据:', existingData);

            // 匹配 <TaskData>xxx</TaskData>
            const taskDataMatch = message.match(/<TaskData>(.*?)<\/TaskData>/s);
            if (taskDataMatch && taskDataMatch[1]) {
              // 解析新任务数据
              const newData = parseEntryContent(taskDataMatch[1].trim());
              console.log('新任务数据:', newData);

              // 合并数据（新数据优先）
              const mergedData = { ...existingData, ...newData };
              console.log('合并后的数据:', mergedData);

              // 更新条目内容
              entry.content = convertToEntryFormat(mergedData, taskId);

              // 使用setLorebookEntries更新条目
              const updatedEntries = await setLorebookEntries(
                lorebooks.primary,
                [{
                  uid: entry.uid,
                  content: entry.content,
                  prevent_recursion: true,
                  enabled:true   ,type: "constant",disable:false

                }]
              );
              console.log('已更新条目:', updatedEntries);
            }
          } else {
            // 如果没有找到匹配的条目，创建新条目
            const taskDataMatch = message.match(/<TaskData>(.*?)<\/TaskData>/s);
            if (taskDataMatch && taskDataMatch[1]) {
              const newData = parseEntryContent(taskDataMatch[1].trim());

              // 创建新条目
              const result = await createLorebookEntries(lorebooks.primary, [
                {
                  comment: taskId,
                  content: convertToEntryFormat(newData, taskId),
                  enabled:true   ,type: "constant",disable:false
                }
              ]);

              console.log('新创建的条目 UID:', result.new_uids);
              console.log('创建的新条目:', result);
            }
          }
        } catch (error) {
          console.error('处理世界书时出错:', error);
        }
      })();
    } else {
      document.getElementById('data-TaskID').style.display = 'none';
    }
  </script>
</html>

